// Кейс: .qa/tests/monitoring/MON-033.md · план: .qa/e2e-app/specs/app.md (1.48)
// Android, беззвучный режим + медиа максимум: строка → лист «בדיקת צליל ההתרעה» → «השמעה» → «שמעתי» → «5 מתוך 5», «המשך» активна.
// ГРОМКО: единственный тест набора с реальным тестовым звуком (звучит и в беззвучном — USAGE_MEDIA); ровно ОДНО нажатие «השמעה».
// Идёт только с BANCI_SOUND=1 (иначе пропуск). Мониторинг НЕ запускается («המשך» не нажимается).
import { assert, skip, openSafetyCheck, withAudio } from '../lib.mjs';

export const name = 'Android «בדיקת בטיחות»: беззвучный режим + медиа max → лист «בדיקת צליל ההתרעה» → «השמעה» → «שמעתי» → «5 מתוך 5», «המשך» активна (ГРОМКИЙ звук, BANCI_SOUND=1) #8edb6e @android @app';

export default async function (app) {
  if (process.env.BANCI_SOUND !== '1') skip('тестовый звук громкий: убедиться, что рядом никого нет / телефон не у уха, и запустить с BANCI_SOUND=1');

  await withAudio(app, { mode: 'SILENT', media: 'max' }, async () => {
    await openSafetyCheck(app);
    const row = await app.waitFor('השמיעו את צליל הבדיקה ואשרו ששמעתם אותו', { timeout: 20000, what: 'строка «השמיעו את צליל הבדיקה…» (SILENT, медиа max)' });
    await app.tapNode(row);
    await app.waitFor('בדיקת צליל ההתרעה', { timeout: 10000, what: 'лист «בדיקת צליל ההתרעה»' });
    await app.tap('השמעה', { exact: true, what: 'кнопка «השמעה» (единственный звук теста)' });
    await app.tap('שמעתי', { exact: true, what: '«שמעתי»' });
    await app.waitGone('בדיקת צליל ההתרעה', { what: 'лист закрылся' });
    await app.waitFor('5 מתוך 5', {
      timeout: 15000,
      what: '«5 מתוך 5» (если другое число — ПРЕДУСЛОВИЕ: батарея > 30% или зарядка, уведомления/камера разрешены, второй телефон подключён)',
    });
    assert(!(await app.exists('עוצמת הקול נמוכה')) && !(await app.exists('עוצמת הקול כבויה')), 'после «שמעתי» нет предупреждения о громкости');
    await app.waitEnabled('המשך', true, { what: '«המשך» после «שמעתי» (5 מתוך 5)' });
  });
  await app.restart();
}
